          "question": "Can I enquire about AC repair if my AC is not cooling?",
          "answer": "Yes. Share the AC type, locality and when the cooling problem began. The cause of an AC not cooling cannot be confirmed without inspection, and any repair scope or charges should be agreed before work starts."
